import TaskCard from "./TaskCard";

export default function TaskList({tasks,reload}){

return(
<div>

<h3>Tasks</h3>

{tasks.map(task=>(
 <TaskCard key={task.id} task={task} reload={reload}/>
))}

</div>
)
}
